function generate(rankIndex=0){const r=RANKS[rankIndex];const attrs={};ATTR.forEach(([k])=>attrs[k]=2+rand(5));const skills={};SKILLS.forEach(([k])=>skills[k]=15+rand(24));return {name:'Шиноби '+(roster.length+1),rank:rankIndex,element:rand(5),attrs,skills,baseAttrs:{...attrs},baseSkills:{...skills},attrPoints:r.at+d6(),skillPoints:r.sp+d6(),gear:{kunai:1,shuriken:2,senbon:0,sword:0,smoke:1,poison:0,paper:0,toxin:0,trap:0,bandage:1,flash:0,poisonBomb:0,potion:1},xp:0,level:1,sprite:24+(roster.length%5),appearanceChosen:false};}
