   if(!game||(!game.animating&&!activeFx&&!fxQueue.length))return false;
   fxQueue.length=0;activeFx=null;game.animating=false;fxRunning=false;
   const pending=fxWaiters.splice(0);for(const resolve of pending){try{resolve()}catch(err){console.error(err)}}
